using System; using System.Collections.Generic; using System.IO; using System.Linq; using System.Threading; using System.Threading.Tasks; using PhotoBooth.Core.Models; using PhotoBooth.Core.Persistence; using PhotoBooth.Core.Services;
namespace PhotoBooth.Business.Services { public sealed class FrameService : IFrameService { private readonly IFrameAnalyzer analyzer; private readonly IFrameRepository repository;private readonly IFileStorageService storage; public FrameService(IFrameAnalyzer a,IFrameRepository r,IFileStorageService storage){analyzer=a;repository=r;this.storage=storage;} public async Task<Frame> ImportAsync(string path,FrameAnalysisOptions options,CancellationToken token){token.ThrowIfCancellationRequested();var frame=analyzer.Analyze(path,options);if(frame.Slots==null||frame.Slots.Count==0)throw new InvalidOperationException("Invalid Frame: no transparent photo slot was detected.");var name=frame.Id.ToString("N")+Path.GetExtension(path);string managedPath;using(var input=File.OpenRead(path))managedPath=await storage.SaveAsync(Path.Combine("Frames",name),input,token);frame.SourcePath=managedPath;frame.CreatedAtUtc=DateTime.UtcNow;frame.ThumbnailPath=managedPath;await repository.SaveAsync(frame,token);return frame;} public Task<Frame> GetAsync(Guid id,CancellationToken token)=>repository.GetAsync(id,token); public Task<IReadOnlyList<Frame>> GetAllAsync(CancellationToken token)=>repository.GetAllAsync(token); public Task DeleteAsync(Guid id,CancellationToken token)=>repository.DeleteAsync(id,token); public async Task SetPinnedAsync(Guid id,bool pinned,CancellationToken token){var all=await repository.GetAllAsync(token);var frame=all.FirstOrDefault(x=>x.Id==id);if(frame==null)throw new InvalidOperationException("Frame not found.");if(pinned&&!frame.IsPinned&&all.Count(x=>x.IsPinned)>=10)throw new InvalidOperationException("A maximum of 10 frames can be pinned.");frame.IsPinned=pinned;await repository.SaveAsync(frame,token);} } }
